function subscribe(cb){var fn=function(e){cb((e&&e.detail)||{});};window.addEventListener('SOTA_MGMT_UPDATE',fn);return fn;}
function clearSub(fn){try{if(fn)window.removeEventListener('SOTA_MGMT_UPDATE',fn);}catch(e){}}
function otaStateCls(st){var s=String(st||'').toLowerCase();if(s==='updated'||s==='verified'||s==='up-to-date')return 'ok';if(s==='failed')return 'crit';if(s==='downloading'||s==='updating'||s==='running')return 'run';if(s===''||s==='pending')return 'pending';return 'warn';}
var backBtn=root.querySelector('#cd-back');var titleEl=root.querySelector('#cd-title');var chipsEl=root.querySelector('#cd-chips');var metaEl=root.querySelector('#cd-meta');var body=root.querySelector('#cd-body');var store=getStore();
function getLiveForDevice(did,dname){var cdata=(ctx&&ctx.data)||[];var vals={};var latestTs=0;var dnl=(dname||'').toLowerCase().trim();var dids=String(did||'').toLowerCase().trim();for(var j=0;j<cdata.length;j++){var row=cdata[j];if(!row||!row.dataKey)continue;var ds=row.datasource||{};var eName=String(ds.entityName||ds.name||'');var eId=ds.entityId;var eIdStr=String(eId&&typeof eId==='object'?eId.id:eId||'').toLowerCase().trim();var rowId=String(row.entityId&&typeof row.entityId==='object'?row.entityId.id:row.entityId||'').toLowerCase().trim();var matches=(eName.toLowerCase().trim()===dnl&&dnl)||(eIdStr&&eIdStr===dids)||(rowId&&rowId===dids)||(eName.toLowerCase().trim()===dids);if(!matches)continue;var pt=lastPoint(row.data);if(!pt)continue;var key=normalizeKey(row.dataKey.name||row.dataKey.label);if(!key)continue;vals[key]=pt.value;if(pt.ts&&pt.ts>latestTs)latestTs=pt.ts;}return{sw_state:vals['sw_update_state']||vals['sw_state']||vals['sw-state']||null,sw_progress:vals['sw_progress']!==undefined?toNum(vals['sw_progress'],null):(vals['sw-progress']!==undefined?toNum(vals['sw-progress'],null):(vals['ota-progress-pct']!==undefined?toNum(vals['ota-progress-pct'],null):null)),sw_version:vals['sw_version']||vals['sw-version']||null,ts:latestTs};}
function draw(){var c=store.selectedCampaign;if(!c){if(body)body.innerHTML='<tr><td colspan="5" style="padding:20px;color:#8aa4be;text-align:center">No campaign selected. Return to Campaigns and click View.</td></tr>';return;}
var st=(c.status||'running').toLowerCase();var cls=st==='failed'?'crit':(st==='completed'?'ok':(st==='warning'?'warn':'run'));if(titleEl)titleEl.textContent=c.name||'Campaign Details';if(chipsEl)chipsEl.innerHTML='<span class="st '+cls+'">'+esc(st.toUpperCase())+'</span>';
var pct=Math.max(0,Math.min(100,toNum(c.progress,0)));
if(metaEl){metaEl.innerHTML='<div class="cd-meta-item"><div class="cd-meta-label">Package</div><div class="cd-meta-val">'+esc((c.packageName||'n/a')+' v'+(c.version||'—'))+'</div></div>'+'<div class="cd-meta-item"><div class="cd-meta-label">Campaign ID</div><div class="cd-meta-val mono">'+esc(c.id||'—')+'</div></div>'+'<div class="cd-meta-item"><div class="cd-meta-label">Mode</div><div class="cd-meta-val">'+esc(c.targetMode||'—')+'</div></div>'+'<div class="cd-meta-item"><div class="cd-meta-label">Devices</div><div class="cd-meta-val">'+esc(String(c.targetCount||0))+'</div></div>'+'<div class="cd-meta-item"><div class="cd-meta-label">Overall Progress</div><div class="cd-meta-val"><div class="prog"><span class="mono">'+pct+'%</span><span class="tr" style="min-width:80px"><span class="fl" style="width:'+pct+'%"></span></span></div></div></div>'+'<div class="cd-meta-item"><div class="cd-meta-label">Last Update</div><div class="cd-meta-val mono">'+esc(c.lastUpdate||'—')+'</div></div>';}
var devices=c.targetDevices||[];if(!devices.length){if(body)body.innerHTML='<tr><td colspan="5" style="padding:20px;color:#8aa4be;text-align:center">No target devices recorded in this campaign.</td></tr>';return;}
var html='';for(var i=0;i<devices.length;i++){var d=devices[i];var live=getLiveForDevice(d.id,d.name);var swState=live.sw_state||'pending';var swProg=live.sw_progress!=null?live.sw_progress:toNum(d.vals&&d.vals['ota-progress-pct'],0);var swVer=live.sw_version||(d.vals&&d.vals['sw-version'])||(d.vals&&d.vals['os-version'])||'—';var lastTs=live.ts||d.latestTs||0;var sCls=otaStateCls(swState);html+='<tr><td><div>'+esc(d.name)+'</div><div class="mono" style="color:#8aa4be;font-size:10px">'+esc(d.id)+'</div></td><td><span class="st '+sCls+'">'+esc(String(swState).toUpperCase())+'</span></td><td><div class="prog"><span class="mono">'+Math.round(swProg)+'%</span><span class="tr"><span class="fl" style="width:'+Math.round(swProg)+'%"></span></span></div></td><td class="mono">'+esc(swVer)+'</td><td class="mono">'+esc(rel(lastTs))+'</td></tr>';}
if(body)body.innerHTML=html||'<tr><td colspan="5" style="padding:20px;color:#8aa4be;text-align:center">No devices found.</td></tr>';}
backBtn&&backBtn.addEventListener('click',function(){try{if(ctx&&ctx.stateController){if(typeof ctx.stateController.resetToDefaultState==='function')ctx.stateController.resetToDefaultState();else if(typeof ctx.stateController.openState==='function')ctx.stateController.openState('default',{},false);}}catch(e){}});
self.__listener=subscribe(function(){draw();});self.__state={draw:draw};draw();};
self.onDataUpdated=function(){if(self.__state)self.__state.draw();};
self.onResize=function(){};
self.onDestroy=function(){clearSub(self.__listener);self.__state=null;};

